@pytest.mark.parametrize("case", CARRY_CASES, ids=[c["id"] for c in CARRY_CASES])
def test_types_carried_across_modules(run, workdir, case):
    """CATCHES: a record or ADT that holds another module's types checked, matched, updated,
    decoded, compared or emitted differently depending on the graph shape, or an
    injected error reported differently."""
    S.check(run, workdir, case, __file__)
